const ELEMENT_PROP_KEYS = new Set(["theme","label","value","x","y","fontWeight","slide","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "Peak",
  value: "2.4k/min",
  x: 0.7,
  y: 0.94,
  fontWeight: 500,
  slide: 26,
  accent: "#3B5BFD",
  fontFamily: "Space Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type CrosshairLockElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CrosshairLockBase>;

const CrosshairLockInner = forwardRef<
  HTMLDivElement,
  CrosshairLockElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CrosshairLock>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CrosshairLockBase
          {...(componentProps as unknown as ComponentProps<typeof CrosshairLockBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CrosshairLock = Interactive.withSchema({
  Component: CrosshairLockInner,
  componentName: "<CrosshairLock>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
